"""Original offline speech generated by Windows; not distributed as product assets."""
from array import array
from pathlib import Path
import random
import subprocess
import sys
import wave
from .integration.test_noqt_host import ROOT
from yingxu.domain.sync_models import stamp


def audio_case(root,seed=20261109,count=40,silent=False):
    source=ROOT/'work/test-results/audio-fixtures/phrase.wav'
    if not source.exists():
        source.parent.mkdir(parents=True,exist_ok=True)
        script=source.with_suffix('.ps1')
        script.write_text("param([string]$Target)\nAdd-Type -AssemblyName System.Speech\n$s=New-Object System.Speech.Synthesis.SpeechSynthesizer\ntry {$s.SetOutputToWaveFile($Target);$s.Speak('The river flows beyond the quiet village and every traveller remembers the way home.')} finally {$s.Dispose()}\n",encoding='utf8')
        subprocess.run(['powershell.exe','-NoProfile','-NonInteractive','-Command',script.read_text(encoding='utf8').replace('param([string]$Target)',"$Target='"+str(source).replace("'","''")+"'")],check=True,timeout=30,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    with wave.open(str(source),'rb') as stream:
        rate,width,channels=stream.getframerate(),stream.getsampwidth(),stream.getnchannels();voice=stream.readframes(stream.getnframes())
    rng=random.Random(seed);parts=[];lines=[];samples=0
    for i in range(count):
        silence=b'\0'*int(rng.uniform(2,6)*rate)*width*channels;parts.append(silence);samples+=len(silence)//(width*channels)
        start=round(samples/rate*1000);clip=voice[:int(rng.uniform(.65,1)*len(voice))//(width*channels)*(width*channels)]
        parts.append(b'\0'*len(clip) if silent else clip);samples+=len(clip)//(width*channels);end=round(samples/rate*1000)
        lines.append(f'{i+1}\n{stamp(start,"srt","00:00:00,000")} --> {stamp(end,"srt","00:00:00,000")}\nGenerated dialogue {i+1}\n')
    path=Path(root)/f'audio-{seed}-{count}-{int(silent)}.wav'
    with wave.open(str(path),'wb') as out:out.setnchannels(channels);out.setsampwidth(width);out.setframerate(rate);out.writeframes(b''.join(parts))
    return path,'\n'.join(lines)
